host_profile.policy:
package cua.policy

# Preserve the user's cursor and foreground app. This only narrows authority.
default allow = false
allow if { approved_tools[input.tool]; not blocked }

# New vendor tools require deliberate admission after their input behavior is reviewed.
approved_tools := {"browser_click", "browser_dialog", "browser_download", "browser_navigate", "browser_pointer", "browser_prepare", "browser_set_input_files", "browser_type", "check_for_update", "check_permissions", "click", "clipboard_read", "clipboard_write", "double_click", "drag", "end_session", "get_accessibility_tree", "get_agent_cursor_state", "get_browser_state", "get_config", "get_cursor_position", "get_desktop_state", "get_recording_state", "get_screen_size", "get_session", "get_session_state", "get_window_state", "health_report", "hotkey", "install_extension", "install_ffmpeg", "launch_app", "list_apps", "list_sessions", "list_windows", "move_cursor", "page", "parse_visual_regions", "press_key", "right_click", "scroll", "set_agent_cursor_enabled", "set_agent_cursor_motion", "set_agent_cursor_theme", "set_config", "set_value", "set_window_frame", "start_recording", "start_session", "stop_recording", "type_text", "verify_state", "zoom"}

input_tools := {"click", "double_click", "right_click", "middle_click", "drag", "scroll", "type_text", "press_key", "hotkey", "set_value"}

blocked if { input.arguments.delivery_mode == "foreground" }
blocked if { input.tool == "bring_to_front" }
blocked if { input.tool == "kill_app" }
# Native menu traversal can activate the application.
blocked if { input.tool == "invoke_menu" }
# Replay cannot certify that every recorded action preserves human input.
blocked if { input.tool == "replay_trajectory" }
blocked if { input.tool == "escalate_session" }
blocked if { input_tools[input.tool]; input.arguments.scope == "desktop" }
blocked if { input_tools[input.tool]; input.arguments.target.kind == "desktop" }
# Rego tool discovery evaluates empty arguments. Native actions reject empty
# input before dispatch because every window-input tool requires a pid.
blocked if { input_tools[input.tool]; input.arguments != {}; not window_addressed }
blocked if { input.tool == "move_cursor"; input.arguments.scope == "desktop" }
blocked if { input.tool == "move_cursor"; input.arguments.target.kind == "desktop" }

window_addressed if { input.arguments.target.kind == "window"; input.arguments.target.pid > 0; input.arguments.target.window_id > 0 }
window_addressed if { input.arguments.pid > 0; input.arguments.window_id > 0 }
window_addressed if { is_string(input.arguments.element_token); startswith(input.arguments.element_token, "s") }

# Visual defaults are part of the host boundary, not an agent preference.
blocked if { input.tool == "set_agent_cursor_theme"; input.arguments != {}; input.arguments.theme_id != "io.botdoctor.cursor.quiet-gray" }
blocked if { input.tool == "set_agent_cursor_theme"; input.arguments != {}; object.get(input.arguments, "reduced_motion", "auto") != "on" }
blocked if { input.tool == "start_session"; theme := input.arguments.cursor_theme; theme != null; theme.theme_id != "io.botdoctor.cursor.quiet-gray" }
blocked if { input.tool == "start_session"; theme := input.arguments.cursor_theme; theme != null; object.get(theme, "reduced_motion", "auto") != "on" }
blocked if { input.tool == "set_config"; startswith(object.get(input.arguments, "key", ""), "cursor.") }
blocked if { input.tool == "set_config"; some key, value in input.arguments; startswith(key, "cursor.") }

effect_names := {"glow", "trail", "magnet", "ripple", "squish"}
blocked if { input.tool == "set_agent_cursor_motion"; some effect in effect_names; input.arguments.effects[effect] == true }
blocked if { input.tool == "start_session"; some effect in effect_names; input.arguments.cursor_motion.effects[effect] == true }
